<!-- Vanilla JS for Micro-Interactions: Filter Pill Toggle & Tooltip feedback -->
<script>
  document.querySelectorAll('.period-btn').forEach(button => {
    button.addEventListener('click', function() {
      document.querySelectorAll('.period-btn').forEach(btn => {
        btn.classList.remove('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
        btn.classList.add('text-on-primary');
      });
      this.classList.add('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
      this.classList.remove('text-on-primary');
    });
  });
</script></main></div>







